/* every address of the original's code the C function stands for (the dev build hooks functions by those addresses); returns how many */
unsigned guest_code_entries(const void *function, uint32_t *out, unsigned max)
{
    unsigned n = 0;
    for (unsigned i = 0; i < sizeof code_table / sizeof code_table[0] && n < max; i++)
        if (code_table[i].function == function)
            out[n++] = code_table[i].address;
    for (unsigned i = 0; i < sizeof code_table2 / sizeof code_table2[0] && n < max; i++)
        if (code_table2[i].function == function)
            out[n++] = code_table2[i].address;
    for (unsigned i = 0; i < sizeof code_table3 / sizeof code_table3[0] && n < max; i++)
        if (code_table3[i].function == function)
            out[n++] = code_table3[i].address;
    for (unsigned i = 0; i < sizeof code_table4 / sizeof code_table4[0] && n < max; i++)
        if (code_table4[i].function == function)
            out[n++] = code_table4[i].address;
    for (unsigned i = 0; i < sizeof code_table5 / sizeof code_table5[0] && n < max; i++)
        if (code_table5[i].function == function)
            out[n++] = code_table5[i].address;
    return n;
}

uint32_t guest_code_address(const void *function)
{
    for (unsigned i = 0; i < sizeof code_table / sizeof code_table[0]; i++)
        if (code_table[i].function == function)
            return code_table[i].address;
    for (unsigned i = 0; i < sizeof code_table2 / sizeof code_table2[0]; i++)
        if (code_table2[i].function == function)
            return code_table2[i].address;
    for (unsigned i = 0; i < sizeof code_table3 / sizeof code_table3[0]; i++)
        if (code_table3[i].function == function)
            return code_table3[i].address;
    for (unsigned i = 0; i < sizeof code_table4 / sizeof code_table4[0]; i++)
        if (code_table4[i].function == function)
            return code_table4[i].address;
    for (unsigned i = 0; i < sizeof code_table5 / sizeof code_table5[0]; i++)
        if (code_table5[i].function == function)
            return code_table5[i].address;
    return 0;
}

void *guest_code(uint32_t address)
{
#ifdef GAME_SDL
    if (address >= 0x54e00 && address < 0x74000 && guest_level_table() == 2) {   /* the blob of level 2 is loaded: its functions are at the level 1 addresses */
        for (unsigned i = 0; i < sizeof code_table2 / sizeof code_table2[0]; i++)
            if (code_table2[i].address == address)
                return code_table2[i].function;
        return 0;
    }
    if (address >= 0x54e00 && address < 0x74000 && guest_level_table() == 3) {   /* the blob of level 3 is loaded */
        for (unsigned i = 0; i < sizeof code_table3 / sizeof code_table3[0]; i++)
            if (code_table3[i].address == address)
                return code_table3[i].function;
        return 0;
    }
    if (address >= 0x54e00 && address < 0x74000 && guest_level_table() == 4) {   /* the blob of level 4 is loaded */
        for (unsigned i = 0; i < sizeof code_table4 / sizeof code_table4[0]; i++)
            if (code_table4[i].address == address)
                return code_table4[i].function;
        return 0;
    }
    if (address >= 0x54e00 && address < 0x74000 && guest_level_table() == 5) {   /* the blob of level 5 is loaded */
        for (unsigned i = 0; i < sizeof code_table5 / sizeof code_table5[0]; i++)
            if (code_table5[i].address == address)
                return code_table5[i].function;
        return 0;
    }
#endif
    unsigned lo = 0, hi = sizeof code_table / sizeof code_table[0];
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        if (code_table[mid].address < address) lo = mid + 1; else hi = mid;
    }
    if (lo < sizeof code_table / sizeof code_table[0] && code_table[lo].address == address)
        return code_table[lo].function;
#ifdef GAME_SDL
    return 0;
#else
    return (void *)(uintptr_t)address;   /* the original's code */
#endif
}
